from pathlib import Path

p = Path('backend/server.js')
s = p.read_text(encoding='utf-8')
if ('/api/admin/role' in s and '/api/admin/rbac/ban' in s and '/api/admin/alert' in s
        and '/api/admin/assign' in s and '/api/public/administration' in s
        and '/api/admin/audit-log' in s and '/api/profile/personal-code/verify' in s):
    print('WETHAQ_ADMIN_BACKEND_ROUTES_ALREADY_OK')
    raise SystemExit(0)

routes = r'''
\n// Wethaq administrative API contract — kept server-side and role-authorized.
app.get('/api/public/administration',(_req,res)=>{const s=adminStructure();res.json({founder:s.founder?{wethaq_id:s.founder.wethaq_id,name:s.founder.name,birth_year:s.founder.birth_year,role:s.founder.role,role_label:s.founder.role_label}:null,deputies:Object.fromEntries(Object.entries(s.deputies).map(([k,v])=>[k,v?{wethaq_id:v.wethaq_id,name:v.name,birth_year:v.birth_year,role:v.role,role_label:roleLabel(v.role)}:null])),members:s.members.map(v=>({wethaq_id:v.wethaq_id,name:v.name,birth_year:v.birth_year,role:v.role,role_label:roleLabel(v.role)}))});});
app.get('/api/admin/role',auth,(req,res)=>{const role=roleOf(req.user?.sub);if(!role)return res.status(403).json({error:'admin_forbidden'});res.json({role,role_label:roleLabel(role)});});
app.get('/api/admin/structure',auth,founderOnly,(req,res)=>res.json(adminStructure()));
app.post('/api/admin/assign',auth,founderOnly,(req,res)=>{const target=resolveUser(req.body?.wethaqId||req.body?.target);const role=String(req.body?.role||'').trim();if(!target||![ROLE_V1,ROLE_V2,ROLE_V3,ROLE_MEMBER].includes(role))return res.status(400).json({error:'invalid_admin_assignment'});if(target.wethaq_id===OWNER_WETHAQ_ID)return res.status(403).json({error:'founder_protected'});const code=newAdminCode(),expiresAt=new Date(Date.now()+365*24*60*60*1000).toISOString();db.prepare('INSERT INTO admin_roles(user_id,role,admin_code_hash,created_by,created_at,expires_at) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,admin_code_hash=excluded.admin_code_hash,created_by=excluded.created_by,created_at=excluded.created_at,expires_at=excluded.expires_at').run(target.id,role,hashCode(code),req.user.sub,now(),expiresAt);audit(req.user.sub,'admin_assigned',target.id,{role});adminEvent(target.id,{type:'role_assigned',role,expires_at:expiresAt});res.status(201).json({ok:true,role,admin_code:code,expires_at:expiresAt});});
app.post('/api/admin/alert',auth,rbac,(req,res)=>{const target=resolveUser(req.body?.wethaqId||req.body?.target);const reason=safeMessage(req.body?.reason||'تنبيه إداري');if(!target||!reason)return res.status(400).json({error:'invalid_alert'});if(target.wethaq_id===OWNER_WETHAQ_ID||roleOf(target.id)===ROLE_FOUNDER)return res.status(403).json({error:'founder_protected'});if(req.adminRole===ROLE_MEMBER)return res.status(403).json({error:'permission_denied'});audit(req.user.sub,'admin_alert',target.id,{reason});adminEvent(target.id,{type:'alert',reason});res.status(201).json({ok:true,target:publicUser(target),reason,confirmed:true});});
app.post('/api/admin/rbac/ban',auth,rbac,(req,res)=>{const target=resolveUser(req.body?.wethaqId||req.body?.target);const minutes=Math.max(0,Number(req.body?.minutes||0));if(!target)return res.status(400).json({error:'user_not_found'});if(target.wethaq_id===OWNER_WETHAQ_ID||roleOf(target.id)===ROLE_FOUNDER)return res.status(403).json({error:'founder_protected'});const targetRole=roleOf(target.id);if(!roleCanBan(req.adminRole,targetRole))return res.status(403).json({error:'permission_denied'});const expires=minutes>0?new Date(Date.now()+minutes*60000).toISOString():null;db.prepare('INSERT INTO bans(user_id,ban_type,expires_at,reason,created_by) VALUES(?,?,?,?,?)').run(target.id,minutes>0?'temporary':'permanent',expires,safeMessage(req.body?.reason||'حظر إداري'),req.user.sub);audit(req.user.sub,'admin_ban',target.id,{minutes,expires});adminEvent(target.id,{type:'ban',expires_at:expires});res.status(201).json({ok:true,confirmed:true,expires_at:expires});});
app.get('/api/admin/audit-log',auth,founderOnly,(req,res)=>{const rows=db.prepare('SELECT * FROM audit_logs ORDER BY id DESC LIMIT 200').all();res.json({logs:rows});});
app.post('/api/profile/personal-code/configure',auth,(req,res)=>{const code=String(req.body?.personalCode||'').trim();if(code.length<4||code.length>128)return res.status(400).json({error:'invalid_personal_code'});db.prepare('UPDATE users SET personal_code_hash=? WHERE id=?').run(hashCode(code),req.user.sub);audit(req.user.sub,'personal_code_configured',req.user.sub);res.json({ok:true,configured:true});});
app.post('/api/profile/personal-code/verify',auth,(req,res)=>{const code=String(req.body?.personalCode||'').trim();const u=db.prepare('SELECT personal_code_hash FROM users WHERE id=?').get(req.user.sub);if(!u?.personal_code_hash||hashCode(code)!==u.personal_code_hash)return res.status(403).json({error:'invalid_personal_code'});res.json({ok:true,verified:true});});
'''
s = s.rstrip() + routes
p.write_text(s,encoding='utf-8')
print('WETHAQ_ADMIN_BACKEND_ROUTES_REPAIR_OK')
